#include <iostream>
#include <string>
#include <vector>

// Simplified example inspired by C++ Primer, demonstrating substring extraction via iterators
struct FileInfo {
    std::string suffix() const { return ".txt"; }  // Example method returning a string
};

int main() {
    std::vector<FileInfo> files(1);  // Container with FileInfo objects
    for (auto it = files.begin(); it != files.end(); ++it) {
        // Simulate: suffix() returns a string, str() might be implied if it's a string stream
        std::string fullSuffix = it->suffix();  // In the original, this might chain to .str()
        std::string extracted = fullSuffix.substr(0, 40);  // Safely extract up to 40 characters
        std::cout << "Extracted substring: " << extracted << std::endl;  // Output for demonstration
    }
    return 0;
}
